// Every account and signal below is fabricated. The example.com URLs are placeholders, not research evidence.
const campaignId = 'synthetic-acquisition-walkthrough';
const accounts = [
  { account_id: 'demo-uae-001', company_name: 'Northstar Logistics (fictional)', region: 'United Arab Emirates', company_type: 'B2B employer', persona: 'People / HR leader (role placeholder)', trigger_signal: 'Synthetic example: People team hiring', source_url: 'https://example.com/demo/northstar-signal', signal_verified: false },
  { account_id: 'demo-uae-002', company_name: 'Harborline Systems (fictional)', region: 'United Arab Emirates', company_type: 'B2B employer', persona: 'People / HR leader (role placeholder)', trigger_signal: 'Synthetic example: regional expansion', source_url: 'https://example.com/demo/harborline-signal', signal_verified: false },
  { account_id: 'demo-uae-003', company_name: 'Cedar Retail Group (fictional)', region: 'United Arab Emirates', company_type: 'Consumer-only example', persona: 'Unverified role', trigger_signal: '', source_url: '', signal_verified: false }
];
return accounts.map((account, index) => ({ json: { ...account, campaign_id: campaignId, variant: index % 2 === 0 ? 'A' : 'B', data_mode: 'synthetic_only', send_enabled: false, authorization: 'not_authorized_for_outreach' } }));

// Illustrative rules only. No real accounts are researched, contacted, or approved here.
const rows = $input.all().map(item => item.json);
const output = rows.map(row => {
  const marketFit = row.region === 'United Arab Emirates';
  const employerFit = row.company_type === 'B2B employer';
  const roleSignal = Boolean(row.persona && row.persona.includes('People / HR leader'));
  const triggerPresent = Boolean(row.trigger_signal && row.source_url);
  const fitScore = (marketFit ? 25 : 0) + (employerFit ? 25 : 0) + (roleSignal ? 20 : 0) + (triggerPresent ? 30 : 0);
  const reviewStatus = !triggerPresent ? 'hold_missing_evidence' : 'human_verification_required';
  const variantCopy = row.variant === 'A'
    ? 'If [verified signal] is current, would it be useful to compare how teams measure participation in employee wellbeing programs?'
    : 'If [verified signal] is current, would it be useful to discuss how teams launch employee wellbeing programs with low operational overhead?';
  return {
    ...row,
    fit_score: fitScore,
    score_explanation: { market_fit: marketFit, b2b_employer_fit: employerFit, role_signal_present: roleSignal, trigger_and_source_present: triggerPresent },
    research_status: row.signal_verified ? 'verified_by_reviewer' : 'unverified_synthetic_placeholder',
    review_status: reviewStatus,
    draft_status: triggerPresent ? 'illustrative_draft_pending_human_review' : 'not_created_missing_evidence',
    draft_message: triggerPresent ? `Hi [verified recipient name] — ${variantCopy} This is sample copy for review only.` : null,
    contact_status: 'not_contacted',
    sent: false,
    send_enabled: false,
    next_action: triggerPresent ? 'Replace placeholders with verified evidence, confirm ICP and offer, then obtain human approval before any real outreach.' : 'Hold until a real source and role are verified.'
  };
});
const reviewQueue = output.filter(row => row.review_status === 'human_verification_required').length;
return [{ json: {
  workflow: 'synthetic_acquisition_walkthrough',
  campaign_id: 'synthetic-acquisition-walkthrough',
  data_mode: 'synthetic_only',
  records_created: output.length,
  review_queue_count: reviewQueue,
  held_for_missing_evidence: output.length - reviewQueue,
  messages_sent: 0,
  send_enabled: false,
  authorization: 'not_authorized_for_outreach',
  interpretation: 'Workflow demonstration only; scores, accounts, signals, and message copy are fabricated and are not company-specific recommendations.',
  accounts: output
} }];
